// The server appends its opt-out line to an SMS body and returns that exact suffix separately;
// split it back off so the body renders as message text and the opt-out grays as auto-added.
export function splitSmsOptOut(
  text: string | null | undefined,
  optOut: string | null | undefined
): { body: string; optOut: string } {
  const t = text ?? '';
  const o = optOut ?? '';
  return o && t.endsWith(o) ? { body: t.slice(0, -o.length), optOut: o } : { body: t, optOut: '' };
}
